class DonChuchoChat{constructor(){this.chatOpen=!1,this.sessionId=null,this.conversationHistory=[],this.backendUrl=this.getBackendUrl(),this.apiKey=this.getApiKey(),this.init()}getBackendUrl(){if(window.DON_CHUCHO_BACKEND_URL)return window.DON_CHUCHO_BACKEND_URL;const e=window.location.hostname;return"localhost"===e||"127.0.0.1"===e?"http://localhost:3000":e.includes("quindiotravel.com.co")?"https://api.quindiotravel.com.co":"http://localhost:3000"}getApiKey(){return window.DON_CHUCHO_API_KEY?window.DON_CHUCHO_API_KEY:null}async init(){try{const e={"Content-Type":"application/json"};this.apiKey&&(e["x-api-key"]=this.apiKey);const a=await fetch(`${this.backendUrl}/api/chat/session`,{method:"POST",headers:e,body:JSON.stringify({source:"web"})});if(a.ok){const e=await a.json();this.sessionId=e.sessionId,console.log("Don Chucho session created:",this.sessionId)}else console.error("Failed to create Don Chucho session"),this.useFallbackMode()}catch(e){console.error("Don Chucho backend not available, using fallback mode:",e),this.useFallbackMode()}}useFallbackMode(){this.fallbackMode=!0,this.sessionId="fallback-"+Date.now(),console.log("Don Chucho running in fallback mode")}async sendMessage(e){if(!e||!e.trim())return;this.chatOpen||this.toggleChat(),this.addMessage(e,"user-message");const a=this.addTypingIndicator();try{let n;if(this.fallbackMode)n=await this.getFallbackResponse(e);else{const a={"Content-Type":"application/json"};this.apiKey&&(a["x-api-key"]=this.apiKey);const s=await fetch(`${this.backendUrl}/api/chat/message`,{method:"POST",headers:a,body:JSON.stringify({message:e,sessionId:this.sessionId,conversationHistory:this.conversationHistory})});if(!s.ok)throw new Error("Backend error");n=(await s.json()).response||await this.getFallbackResponse(e)}await new Promise(e=>setTimeout(e,700)),a&&a.parentNode&&a.remove(),this.addMessage(n,"bot-message")}catch(n){console.error("Error sending message:",n),a&&a.parentNode&&a.remove();const s=await this.getFallbackResponse(e);this.addMessage(s,"bot-message")}}addTypingIndicator(){const e=document.getElementById("don-chucho-messages");if(!e)return null;const a=document.createElement("div");return a.className="message bot-message typing-indicator",a.innerHTML='\n            <div class="message-content">\n                <p>🤠 Don Chucho está escribiendo...</p>\n            </div>\n        ',e.appendChild(a),e.scrollTop=e.scrollHeight,a}async getFallbackResponse(e){const a=e.toLowerCase();return a.includes("precio")||a.includes("costo")||a.includes("tarifa")?"🤠 ¡Vaya, viajero! Nuestros precios varían según el plan:\n\n• Plan 2D/1N: Desde $425.000 COP\n• Plan 3D/2N: Desde $562.000 COP\n• Plan 4D/3N: Desde $777.000 COP\n• Plan 5D/4N: Desde $788.000 COP\n• Plan 6D/4N: Desde $1.008.000 COP\n\nTodo incluye alojamiento, transporte y guías locales RNT 18152. ¿Te gustaría cotizar un plan específico?":a.includes("plan")||a.includes("paquete")?"🤠 ¡Excelente elección, compadre! Tenemos varios planes:\n\n🗺️ **Plan 2D/1N**: Escapada rápida - Parque del Café y PANACA\n🗺️ **Plan 3D/2N**: Aventura natural - Incluye PANACA y Parque del Café\n🗺️ **Plan 4D/3N**: Termales y relax - Termales Santa Rosa incluidos\n🗺️ **Plan 5D/4N**: Experiencia cultural - RECUCA y cultura cafetera\n🗺️ **Plan 6D/4N**: Experiencia definitiva - Todo el Eje Cafetero incluido\n\n¿Cuál te llama más la atención?":a.includes("hotel")||a.includes("alojamiento")||a.includes("finca")?"🤠 ¡Para descansar como en casa! Trabajamos con fincas hoteles certificadas:\n\n🏡 Cabañas La Esmeralda (Estándar) - $1.152.000 cuádruple\n🏡 Finca Hotel Los Girasoles (Intermedia) - $1.588.000 cuádruple\n🏡 Hotel Campestre Café Café (VIP) - $1.770.000 cuádruple\n\nTodas con desayuno incluido y guías locales. ¿Prefieres categoría estándar, intermedia o VIP?":a.includes("salento")?"🤠 ¡Salento es joya del Quindío! Pueblo patrimonio con balcones coloridos y mirador al Valle de Cocora.\n\n✨ Must-see: Mirador Cóndor, Calle Real, artesanías en guadua\n💡 Tips: Sube al mirador al atardecer, lleva cámara para fotos increíbles\n\n¿Quieres incluir Salento en tu viaje?":a.includes("valle")||a.includes("cocora")?"🤠 ¡El Valle de Cocora es espectacular! Palmas de cera de hasta 60 metros de altura, el árbol nacional de Colombia.\n\n✨ Actividades: Senderismo, fotografía, naturaleza, observación de colibríes\n💡 Tips: Lleva botas antideslizantes, agua y protector solar\n\n¿Te gustaría caminar por el bosque nuboso?":a.includes("cafe")||a.includes("parque")?"🤠 ¡El Parque del Café es imperdible! Atracciones mecánicas, shows culturales y el mejor café del mundo.\n\n✨ Incluye: Museo interactivo, shows, 30 atracciones mecánicas\n💡 Tips: Dedica todo el día, compra pasaporte múltiple\n\n¿Eres amante del café, compadre?":a.includes("panaca")?"🤠 ¡PANACA es increíble! Parque agropecuario con 4.500 animales y 10 estaciones temáticas.\n\n✨ Actividades: Interacción con animales, shows educativos, recorridos\n💡 Tips: Planifica mínimo 4 horas, ideal para familias\n\n¿Te gustaría conocer PANACA?":a.includes("termales")||a.includes("santa rosa")?"🤠 ¡Los Termales Santa Rosa son medicina natural! Aguas volcánicas de 45°C ricas en minerales.\n\n✨ Beneficios: Relajación, propiedades terapéuticas, spa\n💡 Tips: Lleva toalla, protector solar, hidratación\n\n¿Quieres un día de relax en los termales?":a.includes("recuca")?"🤠 ¡RECUCA es tradición cafetera pura! Experiencia vivencial del proceso del café.\n\n✨ Actividades: Recolección, beneficio tradicional, cata de café\n💡 Tips: Usa ropa cómoda, cámara para fotos del proceso\n\n¿Te interesa la cultura cafetera?":a.includes("mariposario")||a.includes("mariposa")?"🤠 ¡El Mariposario es mágico! Más de 50 especies de mariposas tropicales en jardines botánicos.\n\n✨ Actividades: Observación, ciclo de vida, conservación\n💡 Tips: Ideal para fotografía macro, visite temprano\n\n¿Te gustan las mariposas?":a.includes("cabalgata")||a.includes("caballo")?"🤠 ¡Las cabalgatas son experiencia auténtica! Recorridos a caballo por paisajes cafeteros.\n\n✨ Rutas: Valles, cafetales, pueblos\n💡 Tips: Ropa cómoda, experiencia previa no necesaria\n\n¿Te animas a montar a caballo?":a.includes("contacto")||a.includes("whatsapp")?"🤠 ¡Para atención personalizada, compadre! Contáctanos:\n\n📱 WhatsApp: +57 317 442 6044\n📧 Email: gerencia@quindiotravel.net\n🌐 Web: www.quindiotravel.com.co\n\nEstamos disponibles 24/7 para ayudarte a planear tu viaje al Eje Cafetero.":a.includes("reserva")||a.includes("cotizar")?"🤠 ¡Perfecto, viajero! Para cotizar tu viaje necesito:\n\n👤 ¿Cuántas personas viajan?\n📅 ¿Cuándo quieres viajar?\n🎯 ¿Qué te interesa más? (café, naturaleza, pueblos, termales)\n💰 ¿Qué presupuesto tienes en mente?\n\nCuéntame estos detalles y te preparo una cotización especial con descuento.":a.includes("hola")||a.includes("buenos")||a.includes("buenas")?"🤠 ¡Hola, compadre! Soy Don Chucho, tu guía del Eje Cafetero. Estoy aquí para ayudarte a planear el viaje perfecto al Quindío.\n\nPuedo ayudarte con:\n• Planes turísticos\n• Precios y cotizaciones\n• Destinos y atractivos\n• Alojamiento y transporte\n\n¿Qué te gustaría saber?":a.includes("gracias")||a.includes("muchas gracias")?"🤠 ¡De nada, compadre! Es un placer ayudarte a descubrir la magia del Eje Cafetero.\n\n¿Hay algo más en lo que pueda ayudarte para tu viaje?":a.includes("filandia")?"🤠 ¡Filandia es encantadora! Pueblo con el mejor mirador del Quindío y artesanías en guadua premium.\n\n✨ Must-see: Mirador 360°, talleres artesanales, gastronomía\n💡 Tips: Compra artesanías de calidad, visita mirador al amanecer\n\n¿Quieres conocer Filandia?":a.includes("armenia")?"🤠 ¡Armenia es la capital del Quindío! Ciudad moderna con acceso a todos los destinos.\n\n✨ Base para: Salento, Filandia, Parque del Café, PANACA\n💡 Tips: Centro de operaciones perfecta, aeropuerto cercano\n\n¿Necesitas información sobre Armenia?":"🤠 ¡Gracias por escribir, compadre! Para darte la mejor respuesta, cuéntame:\n\n• ¿Buscas información sobre planes, destinos o precios?\n• ¿Tienes alguna fecha en mente?\n• ¿Cuántas personas viajan?\n• ¿Qué te interesa más? (café, naturaleza, pueblos, termales)\n\nO contáctanos directamente por WhatsApp al +57 317 442 6044 para atención inmediata."}addMessage(e,a){const n=document.getElementById("don-chucho-messages");if(!n)return;const s=document.createElement("div");s.className=`message ${a}`;const o=document.createElement("div");o.className="message-content";let t=e.replace(/\*\*(.*?)\*\*/g,"<strong>$1</strong>").replace(/\n/g,"<br>");o.innerHTML=`<p>${t}</p>`,s.appendChild(o),n.appendChild(s),n.scrollTop=n.scrollHeight,this.conversationHistory.push({role:"user-message"===a?"user":"assistant",content:e})}toggleChat(){this.chatOpen=!this.chatOpen;const e=document.getElementById("don-chucho-chat"),a=document.getElementById("don-chucho-body"),n=document.getElementById("don-chucho-input");e&&a&&(a.style.display=this.chatOpen?"block":"none",a.classList.toggle("opened",this.chatOpen),e.classList.toggle("don-chucho-open",this.chatOpen),this.chatOpen&&n&&setTimeout(()=>n.focus(),120))}handleDocumentClick(e){const a=document.getElementById("don-chucho-chat");this.chatOpen&&a&&(a.contains(e.target)||this.toggleChat())}handleKeyDown(e){"Escape"===e.key&&this.chatOpen&&this.toggleChat()}sendQuickReply(e){this.chatOpen||this.toggleChat();let a="";switch(e){case"planes":a="Quiero ver los planes disponibles";break;case"precios":a="¿Cuáles son los precios?";break;case"contacto":a="Información de contacto";break;case"destinos":a="¿Qué destinos puedo visitar?"}this.sendMessage(a)}}let donChucho;document.addEventListener("DOMContentLoaded",()=>{donChucho=new DonChuchoChat,window.toggleDonChucho=()=>donChucho.toggleChat(),window.sendDonChuchoMessage=e=>donChucho.sendMessage(e),window.sendDonChuchoQuickReply=e=>donChucho.sendQuickReply(e),window.handleDonChuchoKeyPress=e=>{if("Enter"===e.key){const e=document.getElementById("don-chucho-input");e&&(donChucho.sendMessage(e.value),e.value="")}},document.addEventListener("click",e=>donChucho.handleDocumentClick(e)),document.addEventListener("keydown",e=>donChucho.handleKeyDown(e))}),console.log("Don Chucho chat system loaded");